import{_ as p,a0 as o,w as n,s,ao as i,I as m,x as d,a1 as t,A as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const D=JSON.parse('{"title":"如何使用linux程序mdadm創建軟件RAID1軟陣列 | LCTT x X-CMD","titleTemplate":false,"description":"如何使用linux程序mdadm創建軟件RAID1軟陣列 | LCTT (201502) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何使用linux程序mdadm創建軟件RAID1軟陣列 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何使用linux程序mdadm創建軟件RAID1軟陣列 | LCTT (201502) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201502/20140917 How to create a software RAID-1 array with mdadm on Linux","title":"如何使用linux程序mdadm創建軟件RAID1軟陣列","tag":"201502","desc":""},"relativePath":"201502/20140917 How to create a software RAID-1 array with mdadm on Linux.md","filePath":"[post].md"}'),l={name:"201502/20140917 How to create a software RAID-1 array with mdadm on Linux.md"};function c(f,e,u,b,h,v){const a=o("Link");return n(),s("div",null,[e[13]||(e[13]=i(`<h1 id="如何使用linux程序mdadm創建軟件raid1軟陣列" tabindex="-1">如何使用linux程序mdadm創建軟件RAID1軟陣列 <a class="header-anchor" href="#如何使用linux程序mdadm創建軟件raid1軟陣列" aria-label="Permalink to “如何使用linux程序mdadm創建軟件RAID1軟陣列”">​</a></h1><p>磁盤冗餘陣列(RAID)是將多個物理磁盤結合成一個邏輯磁盤的技術，該技術可以提高磁盤容錯性能，提高磁盤的讀寫速度。根據數據存儲的排列(如：條帶存儲，鏡像存儲，奇偶或者他們的組合)，定義了幾個不同級別的RAID(RAID-0，RAID-1，RAID-5 等等)。磁盤陣列可以使用軟件或者硬件方式實現。現代Linux操作系統中，基本的軟件RAID功能是默認安裝的。</p><p>本文中，我們將介紹軟件方式構建RAID-1陣列(鏡像陣列)，RAID-1將相同的數據寫到不同的設備中。雖然可以使用同一個磁盤的兩個分區實現RAID-1，但是如果磁盤壞了的話數據就都丟了，所以沒什麼意義。實際上，這也是為什麼大多數RAID級別都使用多個物理磁盤提供冗餘。當單盤失效後不影響整個陣列的運行，並且可以在線更換磁盤，最重要的是數據不會丟失。儘管如此，陣列不能取代外部存儲的定期備份。</p><p>由於RAID-1陣列的大小是陣列中最小磁盤的大小，一般來説應該使用兩個大小相同的磁盤來組建RAID-1。</p><h3 id="安裝mdadm" tabindex="-1">安裝mdadm <a class="header-anchor" href="#安裝mdadm" aria-label="Permalink to “安裝mdadm”">​</a></h3><p>我們將使用mdadm（簡稱多盤管理）工具創建、組裝、管理和監控軟件RAID-1。在諸如Fedora、CentOS、RHEL或者Arch Linux 的發行版中，mdadm是默認安裝的。在基於Debian的發行版中，可以使用aptitude 或者 apt-get 安裝mdadm。</p><h4 id="fedora-centos-或-rhel" tabindex="-1">Fedora, CentOS 或 RHEL <a class="header-anchor" href="#fedora-centos-或-rhel" aria-label="Permalink to “Fedora, CentOS 或 RHEL”">​</a></h4><p>由於adadm是預裝的，所以我們只需要開啓RAID守護服務，並將其配置成開機啓動即可：</p><pre><code># systemctl start mdmonitor
# systemctl enable mdmonitor 
</code></pre><p>對於CentOS/RHEL 6系統，使用以下命令：</p><pre><code># service mdmonitor start
# chkconfig mdmonitor on 
</code></pre><h4 id="debian-ubuntu-或-linux-mint" tabindex="-1">Debian, Ubuntu 或 Linux Mint <a class="header-anchor" href="#debian-ubuntu-或-linux-mint" aria-label="Permalink to “Debian, Ubuntu 或 Linux Mint”">​</a></h4><p>在Debian或類Debian系統中，mdadm可以使用 <strong>aptitude 或者 apt-get</strong> 安裝：</p><pre><code># aptitude install mdadm 
</code></pre><p>Ubuntu系統中，會要求配置Postfix MTA 以發送電子郵件通知。你可以跳過去。</p><p>Debian系統中，安裝程序會顯示以下解釋信息，用來幫助我們去判斷是否將根目錄安裝到RAID陣列中。下面的所有操作都有賴於這一步，所以應該仔細閲讀他。</p><p><img src="https://farm4.staticflickr.com/3918/15220883382_c14eb95914_z.jpg" alt=""></p><p>我們不在根目錄使用RAID-1，所以留空。</p><p><img src="https://farm6.staticflickr.com/5555/15198241896_29e08b977f.jpg" alt=""></p><p>提示是否開機啓動陣列的時候，選擇“是”。注意，這裏需要往/etc/fstab 文件中添加一個條目使得系統啓動的時候正確掛載陣列。</p><p><img src="https://farm4.staticflickr.com/3875/15220883342_2b1d689a0a_z.jpg" alt=""></p><h3 id="硬盤分區" tabindex="-1">硬盤分區 <a class="header-anchor" href="#硬盤分區" aria-label="Permalink to “硬盤分區”">​</a></h3><p>現在開始準備建立陣列需要的硬盤。這裏插入兩個8GB的usb磁盤，使用dmesg命令設備顯示設備 /dev/sdb 和 /dev/sdc</p><pre><code># dmesg | less 
</code></pre><hr><p>[ 60.014863] sd 3:0:0:0: [sdb] 15826944 512-byte logical blocks: (8.10 GB/7.54 GiB) [ 75.066466] sd 4:0:0:0: [sdc] 15826944 512-byte logical blocks: (8.10 GB/7.54 GiB)</p><p>我們使用fdisk為每個磁盤建立一個大小為8G的主分區。以下步驟是如何在/dev/sdb上建立分區，假設次磁盤從未被分區(如果有其他分區的話，可以刪掉)：</p><pre><code># fdisk /dev/sdb 
</code></pre><p>按p鍵輸出現在的分區表：</p><p><img src="https://farm4.staticflickr.com/3883/15198241836_24625edcf3_z.jpg" alt=""></p><p>(如果有分區的話，可以使用 d 選項刪除，w 選項應用更改)。</p><p>磁盤上沒有分區，所以我們使用命令 [&#39;n&#39;] 創建一個主分區[&#39;p&#39;], 分配分區號為[&#39;1&#39;] 並且指定大小。你可以按回車使用默認值，或者輸入一個你想設置的值。如下圖：</p><p><img src="https://farm4.staticflickr.com/3875/15034475369_7e72fb9f2e_z.jpg" alt=""></p><p>用同樣的方法為/dev/sdc 分區。</p><p>如果我們有兩個不同容量的硬盤，比如 750GB 和 1TB的話，我們需要在每個磁盤上分出一個750GB的主分區，大盤剩下的空間可以用作他用，不加入磁盤陣列。</p><h3 id="創建-raid-1-陣列" tabindex="-1">創建 RAID-1 陣列 <a class="header-anchor" href="#創建-raid-1-陣列" aria-label="Permalink to “創建 RAID-1 陣列”">​</a></h3><p>磁盤分區完成後，我們可以使用以下命令創建 RAID-1 陣列：</p><pre><code># mdadm -Cv /dev/md0 -l1 -n2 /dev/sdb1 /dev/sdc1 
</code></pre><p>説明：</p><ul><li><strong>-Cv</strong>: 創建一個陣列並打印出詳細信息。</li><li><strong>/dev/md0</strong>: 陣列名稱。</li><li><strong>-l1</strong> (l as in &quot;level&quot;): 指定陣列類型為 RAID-1 。</li><li><strong>-n2</strong>: 指定我們將兩個分區加入到陣列中去，分別為/dev/sdb1 和 /dev/sdc1</li></ul><p>以上命令和下面的等價:</p><pre><code> # mdadm --create --verbose /dev/md0 --level=1 --raid-devices=2 /dev/sdb1 /dev/sdc1 
</code></pre><p>如果你想在在磁盤失效時添加另外一個磁盤到陣列中，可以指定 &#39;--spare-devices=1 /dev/sdd1&#39; 到以上命令。</p><p>輸入 “y” 繼續創建陣列，回車：</p><p><img src="https://farm4.staticflickr.com/3894/15034569970_709bd51718.jpg" alt=""></p><p>可以使用以下命令查看進度：</p><pre><code> # cat /proc/mdstat 
</code></pre><p><img src="https://farm6.staticflickr.com/5565/15221267975_701b819e6d_z.jpg" alt=""></p><p>另外一個獲取陣列信息的方法是：</p><pre><code># mdadm --query /dev/md0
# mdadm --detail /dev/md0 (or mdadm -D /dev/md0) 
</code></pre><p><img src="https://farm6.staticflickr.com/5583/15034683868_6c28564e5a_z.jpg" alt=""></p><p>&#39;mdadm -D&#39;命令提供的信息中，最重要就是陣列狀態類。激活狀態説明陣列正在進行讀寫操作。其他幾個狀態分別為：完成(讀寫完成)、降級(有一塊磁盤失效或丟失)或者恢復中(一張新盤已插入，系統正在寫入數據)。這幾個狀態涵蓋了大多數情況。</p><h3 id="格式化或加載磁盤陣列" tabindex="-1">格式化或加載磁盤陣列 <a class="header-anchor" href="#格式化或加載磁盤陣列" aria-label="Permalink to “格式化或加載磁盤陣列”">​</a></h3><p>下一步就是格式化陣列了，本例中使用ext4格式：</p><pre><code> # mkfs.ext4 /dev/md0 
</code></pre><p><img src="https://farm4.staticflickr.com/3849/15034683838_01e34e7196_z.jpg" alt=""></p><p>現在可以加載陣列並驗證其正常加載：</p><pre><code># mount /dev/md0 /mnt
# mount 
</code></pre><p><img src="https://farm6.staticflickr.com/5554/15034696167_c4fc907c8e_z.jpg" alt=""></p><h3 id="監控磁盤陣列" tabindex="-1">監控磁盤陣列 <a class="header-anchor" href="#監控磁盤陣列" aria-label="Permalink to “監控磁盤陣列”">​</a></h3><p>mdadm工具內置有磁盤陣列監控功能。當mdadm作為守護程序運行的時候(就像我們上文那樣)，會週期性的檢測陣列運行狀態，將檢測到的信息通過電子郵件或者系統日誌報告上來。當然，也可以配置其在發生致命性錯誤的時候調用緊急命令。</p><p>mdadm默認會記錄所有已知分區和陣列的事件，並將他們記錄到 /var/log/syslog中。或者你可以在配置文件中(debian系統：/etc/mdadm/mdadm.conf ，紅帽子系統：/etc/mdadm.conf )用以下格式指定監控設備或者陣列。如果mdadm.conf文件不存在，你可以創建一個。</p><pre><code>DEVICE /dev/sd[bcde]1 /dev/sd[ab]1
 
ARRAY /dev/md0 devices=/dev/sdb1,/dev/sdc1
ARRAY /dev/md1 devices=/dev/sdd1,/dev/sde1
.....
 
# optional email address to notify events
MAILADDR your@email.com
</code></pre><p>編輯完畢mdadm配置文件後，重啓mdadm服務：</p><p>Debian系統，Ubuntu或者Linux Mint:</p><pre><code># service mdadm restart
</code></pre><p>Fedora, CentOS 或 RHEL 7:</p><pre><code># systemctl restart mdmonitor
</code></pre><p>CentOS或者RHEL 6:</p><pre><code># service mdmonitor restart 
</code></pre><h3 id="自動加載陣列" tabindex="-1">自動加載陣列 <a class="header-anchor" href="#自動加載陣列" aria-label="Permalink to “自動加載陣列”">​</a></h3><p>現在我們在/etc/fstab中加入條目使得系統啓動的時候將陣列掛載到/mnt目錄下：</p><pre><code># echo &quot;/dev/md0 /mnt ext4 defaults 0 2&quot; &lt;&lt; /etc/fstab 
</code></pre><p>為了驗證掛載腳本工作正常，我們首先卸載陣列，重啓mdadm，然後重新加載。可以看到/dev/md0已經安裝我們添加到/etc/fstab中的條目加載了：</p><pre><code># umount /mnt
# service mdadm restart (on Debian, Ubuntu or Linux Mint)
or systemctl restart mdmonitor (on Fedora, CentOS/RHEL7)
or service mdmonitor restart (on CentOS/RHEL6)
# mount -a 
</code></pre><p><img src="https://farm6.staticflickr.com/5563/15218183681_63a10da704_z.jpg" alt=""></p><p>現在我們的陣列已經可以訪問了，拷貝文件/etc/passwd到/mnt中測試一下：</p><p><img src="https://farm6.staticflickr.com/5593/15034475219_a3476aec0a_o.png" alt=""></p><p>Debian系統中，需要在/etc/default/mdadm 設置 AUTOSTART 變量為 true 才能使mdadm守護程序在開機時自動加載陣列：</p><pre><code>AUTOSTART=true
</code></pre><h3 id="模擬磁盤丟失故障" tabindex="-1">模擬磁盤丟失故障 <a class="header-anchor" href="#模擬磁盤丟失故障" aria-label="Permalink to “模擬磁盤丟失故障”">​</a></h3><p>我們將使用以下命令卸載磁盤來模擬磁盤故障。注意，在實際應用中，磁盤如果已經是故障狀態了，不需要卸載。</p><p>首先，卸載陣列：</p><pre><code># umount /mnt 
</code></pre><p>現在注意每次執行命令後 &#39;mdadm -D /dev/md0&#39; 的輸出。</p><pre><code># mdadm /dev/md0 --fail /dev/sdb1 #Marks /dev/sdb1 as faulty
# mdadm --remove /dev/md0 /dev/sdb1 #Removes /dev/sdb1 from the array
</code></pre><p>然後，如果你有個備用盤的話，重新添加一下：</p><pre><code> # mdadm /dev/md0 --add /dev/sdb1 
</code></pre><p>數據會被自動添加到備用盤 /dev/sdb1 上：</p><p><img src="https://farm4.staticflickr.com/3855/15221267875_dfc6af8804_z.jpg" alt=""></p><p>注意以上所述步驟只適合支持磁盤熱拔插的系統，在不支持熱拔插的系統中，還是得停止陣列並關機後更換備用盤：</p><pre><code># mdadm --stop /dev/md0
# shutdown -h now 
</code></pre><p>最後將新驅動器重新添加到陣列中：</p><pre><code># mdadm /dev/md0 --add /dev/sdb1
# mdadm --assemble /dev/md0 /dev/sdb1 /dev/sdc1 
</code></pre><p>希望本文對你有所幫助。</p><hr>`,96)),m("p",null,[e[1]||(e[1]=d("via: ",-1)),t(a,{href:"http://xmodulo.com/2014/09/create-software-raid1-array-mdadm-linux.html"},{default:r(()=>[...e[0]||(e[0]=[d("http://xmodulo.com/2014/09/create-software-raid1-array-mdadm-linux.html",-1)])]),_:1})]),m("p",null,[e[5]||(e[5]=d("作者：",-1)),t(a,{href:"http://xmodulo.com/author/gabriel"},{default:r(()=>[...e[2]||(e[2]=[d("Gabriel Cánepa",-1)])]),_:1}),e[6]||(e[6]=d(" 譯者：",-1)),t(a,{href:"https://github.com/shipsw"},{default:r(()=>[...e[3]||(e[3]=[d("shipsw",-1)])]),_:1}),e[7]||(e[7]=d(" 校對：",-1)),t(a,{href:"https://github.com/wxy"},{default:r(()=>[...e[4]||(e[4]=[d("wxy",-1)])]),_:1})]),m("p",null,[e[10]||(e[10]=d("本文由 ",-1)),t(a,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...e[8]||(e[8]=[d("LCTT",-1)])]),_:1}),e[11]||(e[11]=d(" 原創翻譯，",-1)),t(a,{href:"http://linux.cn/"},{default:r(()=>[...e[9]||(e[9]=[d("Linux中國",-1)])]),_:1}),e[12]||(e[12]=d(" 榮譽推出",-1))])])}const R=p(l,[["render",c]]);export{D as __pageData,R as default};
